function esError(status) { return status === 0 || status >= 400; }
function detalleGoogle(r) {
  const b = r && r.body;
  const m = b && b.error && (b.error.message || b.error.status);
  return m ? ' Google dijo: «' + String(m).slice(0, 200) + '».' : '';
}
function mensajeError(status, r, contexto) {
  const d = detalleGoogle(r);
  if (status === 401 || status === 403) {
    return 'Google rechazó la credencial (HTTP ' + status + '): revisa que «' + NOMBRE_CRED +
      '» esté conectada con la cuenta de Ricardo y tenga los scopes de Chat y directory.readonly.' + d;
  }
  if (status === 404) return (contexto || 'El espacio') + ' no existe o Ricardo no es miembro (HTTP 404).' + d;
  if (status === 429) return 'Google limitó las llamadas (HTTP 429). Espera un minuto y vuelve a intentar.' + d;
  if (status === 0) {
    const e = (r && r.error) || {};
    const msg = String(e.message || e.description || (typeof r.error === 'string' ? r.error : '') || '');
    if (/access token|sign without|credential|unauthorized|invalid_grant|refresh/i.test(msg)) {
      return 'n8n no pudo autenticar con Google: la credencial «' + NOMBRE_CRED +
        '» no está conectada o venció. Ábrela en n8n, revisa Client ID / Client Secret y vuelve a hacer «Sign in with Google» con la cuenta de Ricardo. (' + msg.slice(0, 160) + ')';
    }
    return 'No hubo respuesta de Google Chat' + (msg ? ': ' + msg.slice(0, 200) : '.');
  }
  return 'Google Chat respondió HTTP ' + status + '.' + d;
}
function falla(error) { return [{ json: { ok: false, error: String(error) } }]; }
function exito(data) { return [{ json: { ok: true, data } }]; }
function idEspacio(v) {
  v = String(v || '').trim();
  if (!v) return '';
  if (/^spaces\/[A-Za-z0-9_-]+$/.test(v)) return v;
  if (/^[A-Za-z0-9_-]+$/.test(v)) return 'spaces/' + v;
  return '';
}
function isoDesde(v, horas) {
  if (v) {
    const d = DateTime.fromISO(String(v), { setZone: true });
    return d.isValid ? d.toUTC().startOf('second').toISO({ suppressMilliseconds: true }) : null;
  }
  return DateTime.utc().minus({ hours: horas }).startOf('second').toISO({ suppressMilliseconds: true });
}
function indicePar(item) {
  const p = item && item.pairedItem;
  if (p === undefined || p === null) return null;
  if (Array.isArray(p)) return p.length ? p[0].item : null;
  return typeof p === 'object' ? p.item : p;
}
function formatoMensaje(m, mapa, maxChars) {
  const s = m.sender || {};
  const u = mapa[s.name] || {};
  let texto = String(m.text || m.formattedText || '');
  let cortado = false;
  if (maxChars && texto.length > maxChars) { texto = texto.slice(0, maxChars) + '…'; cortado = true; }
  const out = {
    id: m.name,
    autor: u.nombre || s.displayName || (s.type === 'BOT' ? 'App' : (s.name || '')),
    correo: u.correo || '',
    fecha: fechaCL(m.createTime),
    fechaIso: m.createTime || '',
    texto,
    hilo: (m.thread && m.thread.name) || '',
    adjuntos: Array.isArray(m.attachment) ? m.attachment.length : 0,
  };
  if (cortado) out.textoCortado = true;
  if (Array.isArray(m.attachedGifs) && m.attachedGifs.length) out.gifs = m.attachedGifs.length;
  return out;
}

const t = $('Trigger').first().json;
const espacio = idEspacio(t.espacio);
if (!espacio) return [{ json: { error: 'Falta el id del espacio (formato spaces/XXXX). Usa listar_espacios o abrir_dm para obtenerlo.' } }];
const texto = String(t.texto || '').trim();
if (!texto) return [{ json: { error: 'El texto del mensaje está vacío.' } }];
if (texto.length > 4000) return [{ json: { error: 'El mensaje supera los 4.000 caracteres que acepta Google Chat.' } }];
const hilo = String(t.hilo || '').trim();
if (hilo && !/^spaces\/[A-Za-z0-9_-]+\/threads\/[A-Za-z0-9_-]+$/.test(hilo)) return [{ json: { error: 'El hilo debe tener el formato spaces/XXX/threads/YYY (es el campo hilo de leer_mensajes).' } }];
if (hilo && hilo.indexOf(espacio + '/') !== 0) return [{ json: { error: 'El hilo no pertenece al espacio indicado.' } }];
const url = 'https://chat.googleapis.com/v1/' + espacio + '/messages' + (hilo ? '?messageReplyOption=REPLY_MESSAGE_FALLBACK_TO_NEW_THREAD' : '');
const cuerpo = { text: texto };
if (hilo) cuerpo.thread = { name: hilo };
return [{ json: { espacio, texto, hilo, url, cuerpo } }];

