const p = $('Preparar').first().json;
if (p.error) return falla(p.error);
let esp = null;
try { esp = $('Revisar espacio').first().json; } catch (e) { esp = null; }
if (!esp) return falla('No se llegó a revisar el espacio.');
if (esp.error) return falla(esp.error);
let r = null;
try { r = $('POST mensaje').first().json; } catch (e) { r = null; }
if (!r) return falla('No se llegó a enviar el mensaje.');
const st = statusDe(r);
if (esError(st)) return falla(mensajeError(st, r, 'El espacio ' + p.espacio));
const m = r.body || {};
const sid = p.espacio.replace(/^spaces\//, '');
const tid = String((m.thread && m.thread.name) || '').split('/threads/')[1] || '';
const mid = String(m.name || '').split('/messages/')[1] || '';
const base = esp.tipo === 'DIRECT_MESSAGE' ? 'https://chat.google.com/dm/' : 'https://chat.google.com/room/';
const link = base + sid + (tid ? '/' + tid : '') + (mid ? '/' + mid : '');
return exito({
  id: m.name || '',
  espacio: p.espacio,
  nombreEspacio: esp.nombre,
  tipoEspacio: esp.tipo,
  hilo: (m.thread && m.thread.name) || '',
  enHilo: !!p.hilo,
  fecha: fechaCL(m.createTime),
  link,
});
